from lib import *
S = SS('w91')
steps = [
    step("example.com 的证书链(Python 的 ssl.get_verified_chain() 给出的、已验证的链,共 4 张,从叶子到根)。[0] 叶子:CN=example.com,由 Cloudflare TLS Issuing ECC CA 3 签发,公钥 EC secp256r1,签名 ecdsa-with-SHA256,DER 1002 字节;有效期 2026-09-26 ~ 2026-12-25,只有 90 天(现在起还剩 71 天)。[1] 中间 CA:Cloudflare TLS Issuing ECC CA 3,由 SSL.com TLS Transit ECC CA R2 签发,有效期 10 年(3649 天),DER 742 字节。[2] 中间 CA:SSL.com TLS Transit ECC CA R2,由 SSL.com TLS ECC Root CA 2022 签发,公钥 EC secp384r1,DER 824 字节。[3] 根:SSL.com TLS ECC Root CA 2022,自签名,有效期到 2046 年(8759 天),DER 574 字节。整条链 DER 共 3142 字节,是握手时要传输的证书数据的量级(实际线上服务器通常不发根,因为客户端本来就有;这里的 4 张是 Python 验证后构造的链,我没有数线上发了几张)。越靠近叶子,有效期越短:90 天、10 年、15 年、24 年。", t=tl(S(1)), mark=lidx(S(1), '[0] 主体', '[3] 主体'), done=lidx(S(1), '[1] 主体', '[2] 主体', '整条链 DER 总计', 'ssl.get_verified_chain'), b=bars([['叶子 有效期', 90, '90 天'], ['中间 CA 1', 3649, '3649 天'], ['中间 CA 2', 5474, '5474 天'], ['根', 8759, '8759 天']], 8759, mark=[0], done=[1, 2, 3]), kv=KV([['叶子', 'CN=example.com,EC P-256,90 天'], ['中间 CA ×2', '10 年 / 15 年'], ['根', 'SSL.com TLS ECC Root CA 2022,24 年'], ['链总大小', '3142 字节 DER']], ['叶子'])),
    step("叶子证书里的扩展才决定它能做什么。basicConstraints(critical)CA = False——这不是 CA,不能再签发别的证书;keyUsage(critical)digital_signature = True;extendedKeyUsage 只有 serverAuth(只能用作 TLS 服务器证书);subjectAltName 有 2 个名字:example.com 和 *.example.com(现代主机名验证只看 SAN,不看 CN);authorityInfoAccess 给出两个地址——caIssuers(下载签发者证书的 URL)和 OCSP(在线查询吊销状态的服务器);cRLDistributionPoints 给出吊销列表地址;signedCertificateTimestampList 里有 2 个 SCT(证书透明度日志的承诺);certificatePolicies 2 项。", t=tl(S(2)), mark=lidx(S(2), 'basicConstraints', 'subjectAltName', 'extendedKeyUsage'), done=lidx(S(2), 'authorityInfoAccess', 'cRLDistributionPoints', 'keyUsage', 'signedCertificateTimestampList'), kv=KV([['basicConstraints', 'CA = False'], ['extendedKeyUsage', 'serverAuth'], ['subjectAltName', 'example.com、*.example.com'], ['authorityInfoAccess', 'caIssuers + OCSP'], ['SCT', '2 个']], ['subjectAltName'])),
    step("验证链:每一张证书的签名用上一级的公钥验证。[0] 用 [1] 的公钥验证 → 通过;[1] 用 [2] → 通过;[2] 用 [3] → 通过;最后一张 [3] 的主体等于签发者,是自签名的根。本机 Python 的信任库里有 192 张根 / 受信 CA 证书(EC 根 60 张、RSA 根 132 张,到期时间从 2026-11-27 到 2054-12-09——信任库里最早的一张根马上就要过期了);链的最后一张的签发者 “SSL.com TLS ECC Root CA 2022” 在信任库里找到了 1 张同名的,用它验证最后一张的签名也通过。信任是一条从信任库里的根开始、逐级往下用签名担保的链;根本身没有人担保,是靠操作系统 / 浏览器预装的。", t=tl(S(3)), mark=lidx(S(3), '[0] 用 [1]', '[1] 用 [2]', '[2] 用 [3]'), done=lidx(S(3), '链的最后一张', '本机 Python 的信任库里有', '信任库里 EC 根'), b=bars([['信任库 根证书总数', 192, '192'], ['其中 RSA 根', 132, '132'], ['其中 EC 根', 60, '60']], 192, mark=[0], done=[1, 2]), kv=KV([['每一级', '用上一级公钥验签,3 次都通过'], ['信任库', '192 张(EC 60 / RSA 132)'], ['根', '在信任库里找到,验签通过']], ['信任库'])),
    step("各种验证失败(badssl.com 提供的专门配置错误的测试站)。expired.badssl.com → 错误码 10:certificate has expired;wrong.host.badssl.com → 错误码 62:Hostname mismatch, certificate is not valid for 'wrong.host.badssl.com';self-signed.badssl.com → 错误码 18:self-signed certificate;untrusted-root.badssl.com → 错误码 19:self-signed certificate in certificate chain。第五个 revoked.badssl.com 的证书其实已经被吊销,但 Python 的默认设置握手成功了(TLSv1.2),没有报任何错——默认不检查吊销(CRL 或 OCSP)。吊销检查在客户端实现里很不一致,这是一个常见的盲区。", t=tl(S(4)), mark=lidx(S(4), 'revoked.badssl.com', '注意 revoked'), done=lidx(S(4), 'expired.badssl.com', 'wrong.host.badssl.com', 'self-signed.badssl.com', 'untrusted-root.badssl.com'), kv=KV([['过期', '错误码 10'], ['主机名不匹配', '错误码 62'], ['自签名', '错误码 18'], ['链里有自签名(不信任的根)', '错误码 19'], ['已吊销', '握手成功(没检查吊销)']], ['已吊销'])),
    step("SNI 决定服务器给哪张证书,主机名验证再决定客户端认不认。同一个 IP(104.20.23.154)上:SNI = example.com → 默认验证通过,服务器给的证书 SAN 是 [example.com, *.example.com];SNI = www.example.com → 通过(通配符 *.example.com 匹配 www.example.com),给的还是同一张;SNI = example.org → 通过,服务器给了另一张证书,SAN 是 [example.org, *.example.org];SNI = totally-wrong.invalid → 握手失败,服务器直接回 handshake_failure 警报(连不验证也拿不到证书);完全不发 SNI → 同样 handshake_failure。也就是说:这个 IP 上放了多张证书,靠 SNI 区分;证书验证的第二部分是“证书的 SAN 里有我要连的名字”。关掉主机名验证只能得到“链是好的”,不知道对不对站点——忽略证书错误等于允许任何人冒充。", t=tl(S(5)), mark=lidx(S(5), 'SNI = example.org', 'SNI = totally-wrong.invalid', '完全不发 SNI'), done=lidx(S(5), 'SNI = example.com ', 'SNI = www.example.com'), kv=KV([['SNI example.com / www.example.com', '同一张证书(SAN 含 *.example.com)'], ['SNI example.org', '另一张证书'], ['SNI 不认识 / 不发 SNI', 'handshake_failure']], ['SNI example.org'])),
]
A = mkartw('w91', 91, '网络协议,TLS,X.509,证书,信任链,吊销,主机名验证,SNI,真实验证,动画演示',
    '解析 example.com 的 X.509 证书链:叶子 90 天、两个中间 CA 10 与 15 年、根 24 年,三次签名验证都通过,根在本机 192 张的信任库里;叶子的 SAN 是 example.com 与 *.example.com;badssl.com 的过期 / 主机名 / 自签名 / 未知根报错码 10 / 62 / 18 / 19,被吊销的证书却握手成功;同一 IP 上 SNI 决定给哪张证书。',
    'TLS 的安全最终落在一张证书上:你怎么知道对面真的是 example.com?这篇取下 example.com 的证书链,看每一张证书的字段和扩展,亲自用上一级公钥验证每个签名,找到它在信任库里的根,再用几个故意配错的站点看各种验证失败,最后看 SNI 与主机名验证怎么配合。',
    [('90 天', 'example.com 叶子证书的有效期长度(根证书为 8759 天,约 24 年)'), ('10 / 62 / 18 / 19', 'expired、wrong.host、self-signed、untrusted-root 四个测试站在 Python 里的验证错误码'), ('revoked 握手成功', 'Python 默认不检查吊销:revoked.badssl.com 的证书已被吊销,却没有报错')],
    [('证书链', '<p>叶子由中间 CA 签发,中间 CA 由根签发;越靠近叶子有效期越短(90 天 / 10 年 / 15 年 / 24 年)。</p>'),
     ('扩展', '<p>CA = False、serverAuth、SAN、OCSP / CRL 地址、SCT 等扩展决定证书的用途和附属信息。</p>'),
     ('验证签名', '<p>每张证书用上一级公钥验签;根在信任库里找到并验签通过。</p>'),
     ('验证失败', '<p>过期 10、主机名 62、自签名 18、未知根 19;吊销默认不检查。</p>'),
     ('SNI 与主机名', '<p>SNI 决定给哪张证书,SAN 里要有要连的名字;不认识的 SNI 直接 handshake_failure。</p>')],
    steps,
    [ENV_W + '。对 example.com:443 与 badssl.com 的真实连接;证书解析和手动验签用 Python 的 cryptography 库;信任库是 Python 3.14 默认上下文加载的 192 张;revoked.badssl.com 只是 Python 默认设置下的结果,浏览器会做吊销检查',
     '没有验证:OCSP / CRL 的实际查询与 OCSP stapling;证书透明度(SCT)的验证;路径长度和名字约束;交叉签名;证书的吊销在浏览器里的处理(CRLite 等);证书固定;线上服务器实际发送了几张证书(这里只看到 Python 构造的已验证链);ECH'],
    'X.509 与信任链')
